    },
    {
      "indicator": "MM50",
      "reading": "MM50 atua como suporte imediato/nível de referência na região atual.",
      "interpretation": "Suporte técnico de curto-médio prazo; quebra aumenta risco de extensão da baixa."
    },
    {
      "indicator": "MM200",
      "reading": "MM200 está acima do preço e com leve inclinação descendente (resistência de longo/médio prazo).",
      "interpretation": "Tendência de fundo ainda não validou alta; presença de resistência relevante."
    },
    {
      "indicator": "EMA9",
      "reading": "EMA9 próxima da EMA21, sem vantagem clara para compradores.",
      "interpretation": "Reações de curto prazo fracas; cruzamentos recentes apontam perda de momentum."
    },
    {
      "indicator": "EMA21",
      "reading": "EMA21 acompanhando EMA9 com leve viés descendente.",
      "interpretation": "Confirma enfraquecimento do momentum de curto prazo."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD aproximou-se/atravessou a linha de sinal e histograma virou negativo.",
      "interpretation": "Perda de momentum comprador; sinal de correção no curto prazo."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Preço recuou da banda superior para a média/parte inferior; bandas ainda relativamente largas.",
